example.para:
上記のようなXMLファイルをロードするためのコードの実装例を以下に示します。
なお、MyParam要素は不特定多数出現する可能性がある(minOccurs="0"、maxOccurs="unbound")とし、
ExtraParameterについているType属性はMessage Studioによって管理されているデータとします。

// パラメータチェックによって例外処理を発生させてください。
if ( xmlReader == null )
{
	throw new ArgumentNullException( "xmlReader" );
}

// MyParam要素が出現しない可能性も考慮します。
// この場合、後続の処理との相性がよくないため、
// Skipメソッドによって適切な位置までリーダーをジャンプさせます。
if ( xmlReader.IsEmptyElement )
{
	xmlReader.Skip();
	return;
}

// 中身のMyParam要素を読んでいきます。
xmlReader.Read();				// 現在の位置がExtraParameterになっているので、一度Readします。
while( xmlReader.NodeType != XmlNodeType.EndElement )
{
	if ( xmlReader.NodeType == XmlNodeType.Element )
	{
		if ( xmlReader.LocalName == "MyParam" )
		{
			string data = xmlReader[ "value" ];

			// dataを使った何かのユーザー処理をここに記述してください。
			
			// MyParam要素は常に空要素なので、読み込み処理をここでスキップします。
			// これがないと、whileを抜けることが出来なくなります。
			xmlReader.Skip();
			
		}
		else
		{
			// ExceptionHelperによって例外の生成処理を簡略化できます。
			throw ExceptionHelper.CreateUnknownXmlElementException( xmlReader );
		}
	}
	else
	{
		if ( !xmlReader.Read() )
		{
			throw ExceptionHelper.CreateXmlBrokenException( xmlReader );
		}
	}
}
xmlReader.ReadEndElement();		// 要素の終了位置を適切な位置へジャンプさせます。

