子供ウィンドウのシリアライズ / デシリアライズ処理にプラグイン側から独自の処理を加える例を示します。
独自のウィンドウクラスを定義します。

public class MyWindow : ChildWindowBase
{
	public MyWindow()
	{
		InitializeComponent();
		this.PersistString = "MyWindow";	// シリアライズ文字列を設定します。
	}
}

復元処理を記述します。
プラグインの処理の中で以下のようにイベントハンドラを登録します。
登録されたイベントハンドラは、プラグインの終了処理で必ず開放してください。
そうしない場合、ユーザーがメニュー上から「プロジェクトを閉じる」を選択した場合に
予期せぬ不具合を誘発する可能性もあります。
プラグインの初期化および終了処理について、詳細はの解説もご覧ください。

private PluginInitArgs pluginArgs = null;

public void SetupPlugin( PluginInitArgs args )
{
	this.pluginArgs = args;
	
	if ( this.pluginArgs.FormMain != null )		// nullチェックを忘れないでください。
	{
		this.pluginArgs.FormMain.ChildWindowDeserializing += new EventHandler< ChildWindowDeserializeEventArgs >( deserialize );
	}
	
	// そのほかの初期化コードは省略します
}

public void TearDownPlugin()
{
	if ( this.pluginArgs.FormMain != null )
	{
		// ここで外すようにしないとプロジェクトを閉じても監視が続きますので注意してください。
		this.pluginArgs.FormMain.ChildWindowDeserializing -= deserialize;
	}
}

public void TearDownPlugin()
{
	if ( this.pluginArgs.FormMain != null )		// ここにもnullチェックを入れます。
	{
		this.pluginArgs.FormMain.ChildWindowDeserializing -= deserialize;
	}
}

次に、以下のように、デシリアライズの処理を追加します。

private void deserialize( object sender, ChildWindowDeserializeEventArgs e )
{
	if ( e.CreatedWindow == null )	// すでに他のルーチンで作成されている場合があるので無視してください
	{
		if ( e.PersistString == "MyWindow" )
		{
			e.CreatedWindow = new MyWindow();
		}
	}
}

独自ウィンドウクラスのコンストラクタで、このプロパティを設定しない処理の場合、
イベントハンドラは以下のように書き換えてください。

private void deserialize( object sender, ChildWindowDeserializeEventArgs e )
{
	if ( e.CreatedWindow == null )	// すでに他のルーチンで作成されている場合があるので無視してください
	{
		if ( e.PersistString == typeof( MyWindow ).GUID.ToString() )
		{
			e.CreatedWindow = new MyWindow();
		}
	}
}

