以下の例では、ファイルは必ずテキスト行は3個でなくてはならず、
各テキスト行は"JP"という名前の言語セルを含む必要がある、というルールに則ってエラーを出力するような処理です。

if ( file.Children.Count != 3 )
{
	yield return new ChildrenNotThreeError();
}
foreach( TextData child in file.Children )
{
	if ( !child.LanguageCells.ContainsKey( "JP" ) )
	{
		yield return new JapaneseCellNotContainedError();
	}
}

