そのようなタグに字間を入れるべきではありません。
そこで、実装はたいていの場合以下のように行っていただく形になります。

bool NeedCharspaceAfter( CalcTagWidthArgs args )
{
	return CalculateWidthValue( args ) != 0.0f;
}

remarks.para:
             このクラスのバージョンごとの更新履歴を示します。
             


            		Ver1.1.x系
            		
            			このクラスは、名前と名前空間が変更されました。
            		
             


            		Ver1.1.x系
            		
            			このクラスは、インターフェイスを実装するように宣言されました。
            		
             


            		Ver1.1.x系
            		
            			このクラスは、インターフェイスを実装するように宣言されました。
            			それに伴い、CharSpaceプロパティおよびLineSpaceプロパティは廃止され、
            			それぞれプロパティおよびプロパティとなりました。
            		
             


            		Ver1.2.x系
            		
            			メソッドおよびプロパティが追加されました。
            			また、メソッド中で行っていた処理を
            			メソッド中に移行しました。これにより、このクラスを継承してパラメータを拡張したようなプラグインをより容易に作成することができるようになりました。例として以下のように
            			各メソッドおよびプロパティをオーバーライドすることで容易にパラメータを拡張することができます。
            			
            			// 拡張レンダーモードクラス
            			public class ExRenderModeParameters : NW4RParameters
            			{
            				// 拡張パラメータ
            				public virtual string ExParameter
            				{
            					get;
            					set;
            				}
             
            				// RootElementNameプロパティをオーバライド
            				protected override string RootElementName
            				{
            					get { return "ExRenderModeParams"; }
            				}
            				
            				// ReadRootElementメソッドのオーバーライド
            				protected override void ReadRootElement( XmlReader xmlReader )
            				{
            					// NW4Rのパラメータ
            					base.ReadRootElement( xmlReader );
            		
            					// 拡張パラメータ
            					this.ExParameter = xmlReader["ExParameterAttributeName"];
            				}
            
            				// WriteRootElementメソッドのオーバーライド
            				protected override void WriteRootElement(XmlWriter xmlWriter)
            				{
            					// NW4Rのパラメータ
            					base.WriteRootElement(xmlWriter);
            					
            					// 拡張パラメータ
            					xmlWriter.WriteAttributeString( "ExParameterAttributeName", this.ExParameter );
            				}
            			}

member.example:
以下のようなコードを記述してコマンドを発行できます。

// 変更対象の変数
int target = 24;
// 管理するマネージャ
CommandManager man = new CommandManager();


// ここに、値が変更される前の状態を保存しておきます。
// ローカル変数として記述することができます。
int before = target;

Command com = new Command
(
	delegate()
	{
		// ここに、コマンドが実行された時に行う処理を記述します
		target = 33;		// 指定された情報にtargetを変更します
	},
	delegate()
	{
		// ここに、コマンドが巻き戻るときに行う処理を記述します
		target = before;	// ここに、ローカル変数を指定することができます。
	}
);

// コマンドを発行します
man.ExecuteCommand( man );
